INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='era-1996'), 'employment_uk', 'UK', 'Employment Rights Act 1996 s.126', 'http://www.legislation.gov.uk/ukpga/1996/18/section/126', 'Employment Rights Act 1996', 'Acts which are both unfair dismissal and discrimination.', 'Acts which are both unfair dismissal and discrimination. 126 1 This section applies where compensation falls to be awarded in respect of any act both under -  a the provisions of this Act relating to unfair dismissal, and b the Equality Act 2010. 2 An employment tribunal shall not award compensation under either of those Acts in respect of any loss or other matter which is or has been taken into account under the other by the tribunal (or another employment tribunal ) in awarding compensation on the same or another complaint in respect of that act.', 308, '3521202beb3a80f315da92467a7883d68a3ed55fabe8ec98417c3fec4f1f581e', 'legislation', '2026-04-06', true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
