INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='era-1996'), 'employment_uk', 'UK', 'Employment Rights Act 1996 s.127A', 'http://www.legislation.gov.uk/ukpga/1996/18/section/127A', 'Employment Rights Act 1996', 'Internal appeal procedures.', 'Internal appeal procedures. 127A . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . . .', 310, 'cfaae73a6f03e6d21eaf686557316df06fffb1d69fd7bd34da57b5ae2bd633e0', 'legislation', '2026-04-06', true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
