INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='eta-1996'), 'employment_uk', 'UK', 'Employment Tribunals Act 1996 s.45', 'http://www.legislation.gov.uk/ukpga/1996/17/section/45', 'Employment Tribunals Act 1996', 'Repeals and revocations.', 'Repeals and revocations. 45 The enactments specified in Part I of Schedule 3 are repealed, and the instruments specified in Part II of that Schedule are revoked, to the extent specified in the third column of that Schedule.', 84, 'cf62bd484e6784be40cc75bf7f43c694abb1bc4a1e80e491968fae7bcfa2d5cc', 'legislation', '2026-04-07', true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='eta-1996'), 'employment_uk', 'UK', 'Employment Tribunals Act 1996 s.46', 'http://www.legislation.gov.uk/ukpga/1996/17/section/46', 'Employment Tribunals Act 1996', 'Commencement.', 'Commencement. 46 This Act shall come into force at the end of the period of three months beginning with the day on which it is passed.', 85, '724fdca1f6dcd69ed471ef569321c9dc5397b49f6c0de421fc41f2a6ce3603e8', 'legislation', '2026-04-07', true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
