INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-dismissals'), 'employment_uk', 'EW', 'What dismissal is - Dismissals - Acas (https://www.acas.org.uk/dismissals)', 'https://www.acas.org.uk/dismissals', 'What dismissal is - Dismissals - Acas', 'What dismissal is - Dismissals - Acas', 'Dismissals with and without notice Constructive dismissal Following a fair procedure A dismissal is when an employer ends an employee''s contract. It usually means the same as being sacked or fired. It''s important that an employer uses a fair and reasonable procedure to decide whether to dismiss someone. For a dismissal to be fair, the employer must: have a valid reason – read about types of dismissal and reasons to dismiss someone fairly make a decision that''s balanced, consistent and as fair as possible The employer should follow a full and fair procedure, usually in line with the Acas Code of Practice on disciplinary and grievance procedures. The procedure an employer follows will be taken into account if an employee claims for unfair dismissal and the case reaches an employment tribunal.', 0, '4f9617ce4dabd07b525cc10dc5804e25d8be9a06644d13424c246dcf1df38bdd', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-dismissals'), 'employment_uk', 'EW', 'What dismissal is - Dismissals - Acas (https://www.acas.org.uk/dismissals)', 'https://www.acas.org.uk/dismissals', 'What dismissal is - Dismissals - Acas', 'Giving the reasons for dismissal', 'If an employer dismisses an employee, they should tell them: why they have been dismissed when their employment contract will end their notice period, if there is one their right to appeal the decision It''s a good idea to put it in writing, for example in a letter or email.', 1, '1747cf42f8bb55cd1be49e4d49fe758a52a47d5637b952b9878633e5ab4028de', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-dismissals'), 'employment_uk', 'EW', 'What dismissal is - Dismissals - Acas (https://www.acas.org.uk/dismissals)', 'https://www.acas.org.uk/dismissals', 'What dismissal is - Dismissals - Acas', 'When an employer must put the reasons in writing', 'Regardless of how long someone''s been employed, an employer must put the reasons in writing for: employees on maternity or adoption leave Other employees have the right to ask their employer for a written statement giving the reasons for their dismissal if they have: the legal status of employee been employed for 2 years If an employee asks, their employer must give them the reasons in writing within 14 days.', 2, '3e1455ca5571a4d2c9aa3870b1c84cf903bd6558ec5f608b30746a288a0b47fc', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-dismissals'), 'employment_uk', 'EW', 'What dismissal is - Dismissals - Acas (https://www.acas.org.uk/dismissals)', 'https://www.acas.org.uk/dismissals', 'What dismissal is - Dismissals - Acas', 'If an employee believes the dismissal is unfair', 'An employee can appeal against a dismissal. The employer must follow a fair and reasonable procedure. Otherwise the employee might be able to make a claim for unfair dismissal, even if the reason for dismissal was valid. If an employee gets their job back after appealing a dismissal, this is known as a ''vanishing dismissal''. This means they cannot make a claim to an employment tribunal for unfair dismissal. Find out what employees can do if they think a dismissal is unfair', 3, '6deb6b9a66a4cee5bbea67dce859a968036d42fd47b82bd61ceb9d4b16b53739', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-dismissals'), 'employment_uk', 'EW', 'What dismissal is - Dismissals - Acas (https://www.acas.org.uk/dismissals)', 'https://www.acas.org.uk/dismissals', 'What dismissal is - Dismissals - Acas', 'Telling other people at work', 'Employers should respect the confidentiality of the person who''s been dismissed. For example, when they tell the people they worked with and clients that the employee has left. Any outcome of a disciplinary procedure should remain confidential. Find out more about talking to staff after a disciplinary procedure', 4, 'ed0b118d15693c9ebb8358a090a72f219e620ae25da9639ea12d7c92a2e63b66', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-dismissals'), 'employment_uk', 'EW', 'What dismissal is - Dismissals - Acas (https://www.acas.org.uk/dismissals)', 'https://www.acas.org.uk/dismissals', 'What dismissal is - Dismissals - Acas', 'Settlement agreements', 'A settlement agreement is sometimes used to end an employment relationship when both sides agree it''s no longer working. This can include some dismissal situations. If someone signs a settlement agreement, they cannot make an unfair dismissal claim to an employment tribunal. Find out more about settlement agreements If you''re thinking about using a settlement agreement, you should get legal advice.', 5, '08b1d7f628192505731fb9a2f51f979f395c40772deeaf4de1d92ffa40728aed', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-disciplinary-grievance'), 'employment_uk', 'EW', 'Discipline and grievance | Acas (https://www.acas.org.uk/disciplinary-and-grievance-procedures)', 'https://www.acas.org.uk/disciplinary-and-grievance-procedures', 'Discipline and grievance | Acas', 'Discipline and grievance | Acas', 'Workers and employers can often raise and deal with problems at work early and informally. When that''s not possible, they can use formal disciplinary and grievance procedures. Employers must follow the Acas Code of Practice. It says how they should follow fair procedures.', 0, 'b2263063fb8bc40a0a2defb5fff24fdb9d22e03ca5c1592f7b988668047b72ff', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
