INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-disciplinary-grievance'), 'employment_uk', 'EW', 'Discipline and grievance | Acas (https://www.acas.org.uk/disciplinary-and-grievance-procedures)', 'https://www.acas.org.uk/disciplinary-and-grievance-procedures', 'Discipline and grievance | Acas', 'Suspension during an investigation at work letter', 'Telling a worker why they have been suspended and what happens next.', 10, '01eacebb05cc72faee65966a6ceb8cd0c3d978131fc63df84e77cb345c65c18b', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-disciplinary-grievance'), 'employment_uk', 'EW', 'Discipline and grievance | Acas (https://www.acas.org.uk/disciplinary-and-grievance-procedures)', 'https://www.acas.org.uk/disciplinary-and-grievance-procedures', 'Discipline and grievance | Acas', 'Acas Code of Practice on disciplinary and grievance procedures', 'The minimum standards an employer should follow for any disciplinary or grievance case.', 11, '28efb9fa822d04fcdd19d854c20bf813ea3e8d85369884ef1100497e49a47e34', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-early-conciliation'), 'employment_uk', 'EW', 'What early conciliation is - Early conciliation - Acas (https://www.acas.org.uk/early-conciliation)', 'https://www.acas.org.uk/early-conciliation', 'What early conciliation is - Early conciliation - Acas', 'What early conciliation is - Early conciliation - Acas', 'What early conciliation is Requesting it as an employer How the process works Conciliation up to and during tribunal Using a representative If you''re being taken to tribunal Getting paid as part of an Acas settlement Early conciliation is a legal process. You must notify Acas if you want to make a claim to an employment tribunal. We will then offer early conciliation. During early conciliation, an Acas conciliator tries to help you reach a legal agreement with your employer. This can help you avoid going to an employment tribunal.', 0, '8538c1ea8c2aab96bf032de8bff9931ea2662a96f3025e703de2415b985ea5cc', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-early-conciliation'), 'employment_uk', 'EW', 'What early conciliation is - Early conciliation - Acas (https://www.acas.org.uk/early-conciliation)', 'https://www.acas.org.uk/early-conciliation', 'What early conciliation is - Early conciliation - Acas', 'What Acas cannot do', 'Early conciliation is only for people who are considering making a claim to an employment tribunal. During early conciliation, Acas cannot: represent you – we are not a trade union take your or your employer''s side help you prepare your case for employment tribunal tell you if you have a valid case give you legal advice Find out how to get legal advice', 1, '9ed138ebbbbd63eb3e335f8754384d6c4ae32cf344705ad297eed06a3e6cfde4', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-early-conciliation'), 'employment_uk', 'EW', 'What early conciliation is - Early conciliation - Acas (https://www.acas.org.uk/early-conciliation)', 'https://www.acas.org.uk/early-conciliation', 'What early conciliation is - Early conciliation - Acas', 'Before you notify Acas', 'Early conciliation should not be your first step. It is usually easier and quicker to try to solve things informally. Before you notify Acas, you should try to: raise the problem informally raise a formal grievance – this is making a formal complaint to your employer appeal to your employer – if you feel your disciplinary or grievance outcome was wrong or unfair At an employment tribunal, the judge will usually expect you to show that you tried to resolve the dispute yourself. If you do not, it could affect how much compensation you get if your claim is successful.', 2, '7e7da162e75b35ce934373297d3527eeaf154f40b7dd4d8dd6ecb24fc195499f', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='acas-early-conciliation'), 'employment_uk', 'EW', 'What early conciliation is - Early conciliation - Acas (https://www.acas.org.uk/early-conciliation)', 'https://www.acas.org.uk/early-conciliation', 'What early conciliation is - Early conciliation - Acas', 'Notify Acas about making a claim', 'You should only notify Acas if you are considering making a claim to an employment tribunal. When you notify us, we''ll offer you early conciliation. Early conciliation is voluntary. You and your employer can choose whether to take part. Notify Acas about making a claim to an employment tribunal', 3, '28b67db735ca0ee1fd968a3a5f90e081276f75606aa590626904a28a5aec92e5', 'acas_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-et-make-a-claim'), 'employment_uk', 'EW', 'Make a claim to an employment tribunal (https://www.gov.uk/employment-tribunals/make-a-claim)', 'https://www.gov.uk/employment-tribunals/make-a-claim', 'Make a claim to an employment tribunal', 'Make a claim', 'You can make a claim: for yourself, as the only person claiming for yourself and others who’ve been treated in the same way for someone else, if you’re acting as their representative You usually have to make a claim to the tribunal within 3 months of your employment ending or the problem happening. You’ll usually need an early conciliation certificate for each respondent before you make a claim. You can get these from Acas (Advisory, Conciliation and Arbitration Service). If you have a disability or health condition that could affect you taking part in a hearing, you can let the tribunal know you’ll need reasonable adjustments. Tell the tribunal if you need adjustments when you make your claim or at any time during the claim process. You should also read the guidance for whistleblowing if it relates to your claim.', 0, '0d33127121de075a81e5cabd17718ed67a91ae64ab043bc61e13ad7fc42a7e8d', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-et-make-a-claim'), 'employment_uk', 'EW', 'Make a claim to an employment tribunal (https://www.gov.uk/employment-tribunals/make-a-claim)', 'https://www.gov.uk/employment-tribunals/make-a-claim', 'Make a claim to an employment tribunal', 'What it costs', 'You do not have to pay a fee to make a claim to an employment tribunal. You may have to pay other costs, for example: the costs of the people or organisations you’re claiming against (the ‘respondents’) if the tribunal decides you’ve acted unreasonably', 1, 'bb3bbb373076ba0b5e87ab7328518911b41f43a74b0f51332f4ce148d82f983a', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-et-make-a-claim'), 'employment_uk', 'EW', 'Make a claim to an employment tribunal (https://www.gov.uk/employment-tribunals/make-a-claim)', 'https://www.gov.uk/employment-tribunals/make-a-claim', 'Make a claim to an employment tribunal', 'Make a claim online', 'Before you start, you’ll need: the names and addresses of all the people making the claim (the ‘claimants’) the names and addresses of the respondents - you can find this in your job offer letter, your employment contract or your payslips your Acas early conciliation certificate numbers', 2, '3598d1ffeb6fe16ce6a967e5e5efef73906895596986125549381f42a869a902', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-et-make-a-claim'), 'employment_uk', 'EW', 'Make a claim to an employment tribunal (https://www.gov.uk/employment-tribunals/make-a-claim)', 'https://www.gov.uk/employment-tribunals/make-a-claim', 'Make a claim to an employment tribunal', 'If you’ve already started a claim', 'You can return to an existing claim to continue your application or view your submitted applications.', 3, 'bf82b8f8e84946e05b6a0362bc1847175ca59f4bdd320a0886c5d0501039291e', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-et-make-a-claim'), 'employment_uk', 'EW', 'Make a claim to an employment tribunal (https://www.gov.uk/employment-tribunals/make-a-claim)', 'https://www.gov.uk/employment-tribunals/make-a-claim', 'Make a claim to an employment tribunal', 'Make a claim by post', 'You can also download and fill in a claim form. Send your completed form to one of the following addresses, depending on where you were working. Employment tribunal central office (England and Wales)PO Box 11225Crown HouseLoughboroughLE11 9PX Employment tribunal central office (Scotland)PO Box 27105GlasgowG2 9JR You can also deliver it in person to a main Employment Tribunal office. Find a full list of offices in the guidance about making a claim.', 4, '406ff5b396031197fb89cd5eb066d3b4b9f6e1112fea67292a5d3b289b719056', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-et-make-a-claim'), 'employment_uk', 'EW', 'Make a claim to an employment tribunal (https://www.gov.uk/employment-tribunals/make-a-claim)', 'https://www.gov.uk/employment-tribunals/make-a-claim', 'Make a claim to an employment tribunal', 'If you’re having technical issues or need guidance about how to claim', 'Call the employment tribunal customer contact centre. England or Wales employment tribunal customer contact centre Telephone: 0300 323 0196 Welsh language: 0300 303 5176 Relay UK (if you cannot hear or speak on the phone): 18001 then 0300 323 0196 Monday to Friday, 9am to 5pm Find out about call charges Scotland employment tribunal customer contact centre Telephone: 0300 790 6234 Relay UK (if you cannot hear or speak on the phone): 18001 then 0300 790 6234 Monday to Friday, 9am to 5pm Find out about call charges', 5, '47ae9dca2bafc3516a15b033bcddd9a01921b3e6d82fe6cafdb5fb8750fc5ec9', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-et-make-a-claim'), 'employment_uk', 'EW', 'Make a claim to an employment tribunal (https://www.gov.uk/employment-tribunals/make-a-claim)', 'https://www.gov.uk/employment-tribunals/make-a-claim', 'Make a claim to an employment tribunal', 'If you do not have access to the internet or do not feel confident using it', 'We Are Group support@wearegroup.com Telephone: 03300 160 051 Monday to Friday, 9am to 5pm Closed on bank holidays Text FORM to 60777 and someone will call you back Find out about call charges', 6, '5aa12f5d10c23bf0c426fe9bf8844be8e666bcec22ca590e4d59364b54243404', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-redundancy'), 'employment_uk', 'EW', 'Redundancy: your rights (https://www.gov.uk/redundancy-your-rights)', 'https://www.gov.uk/redundancy-your-rights', 'Redundancy: your rights', 'Overview', 'Redundancy is a form of dismissal from your job. It happens when employers need to reduce their workforce. If you’re being made redundant, you might be eligible for certain things, including: a consultation with your employer the option to move into a different job time off to find a new job You also have specific rights if your employer is insolvent. You must be selected for redundancy in a fair way, for example because of your level of experience or capability to do the job. You cannot be selected because of age, gender, or if you’re disabled or pregnant. If you are, this could be classed as an unfair dismissal.', 0, '81cde0f3270bf7ad84d54bb11838b27db76c08ef5c19aacaaa6764a2f98d664b', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-redundancy'), 'employment_uk', 'EW', 'Redundancy: your rights (https://www.gov.uk/redundancy-your-rights)', 'https://www.gov.uk/redundancy-your-rights', 'Redundancy: your rights', 'Get advice', 'You can get advice on redundancy from Acas (Advisory, Conciliation and Arbitration Service) or Citizens Advice.', 1, 'ad86afe619cf8b484abe97d48bcc5c7a4f5d4e173e0e82b7d0483ec766a6cd71', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Entitlement', 'Almost all people classed as workers are legally entitled to 5.6 weeks’ paid holiday a year (known as statutory leave entitlement or annual leave). workers with ‘irregular hours’ (where the number of hours they work in a pay period often or always changes) ‘part-year’ workers (where there are periods of at least a week in a leave year where they do not need to work and are not paid) An employer can include bank holidays as part of statutory annual leave.', 0, 'b1c80f49604bc12907e63e3f3dfee2b8707141d8f76e197b9c9e3d85012672bd', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Statutory annual leave entitlement', 'Most workers who work a 5-day week must receive at least 28 days’ paid annual leave a year. This is the equivalent of 5.6 weeks of holiday.', 1, 'f5ce8d2d6a670f6c5266d1539fb88a7849b1e4f085442f369d1a059132f1baaf', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Working part-time', 'Part-time workers who work regular hours for the whole year are entitled to at least 5.6 weeks’ paid holiday, but this will amount to fewer than 28 days. For example, if they work 3 days a week, they must get at least 16.8 days’ leave a year (3 × 5.6). Use the holiday entitlement calculator to work out a part-time worker’s leave.', 2, 'a96fc34a33a92d13eedf6b080c8a5a729df03fbd1714cfcb162858805d830b4c', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Working irregular hours or for part of the year', 'People working irregular hours or part of the year are entitled to up to 5.6 weeks statutory leave. They will build up (‘accrue’) leave depending on the hours they’ve already worked, rather than getting a fixed number of days or hours. Use the holiday entitlement calculator to work out how much leave they’ve accrued in a pay period. For leave years beginning on or before 31 March 2024, leave entitlement for irregular-hours and part-year workers does not need to be accrued based on hours they’ve already worked. You can use the holiday entitlement calculator to estimate their entitlement based on the average days or hours they work each week.', 3, '85cd5738cbe0a8e622c88a4030585cfdcced0e238b613a0f437644d5dfd6b0de', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Limits on statutory leave', 'Statutory paid holiday entitlement is limited to 28 days. For example, staff working 6 days a week are only entitled to 28 days’ paid holiday.', 4, '2d342df9cd553aff8fefbc994be0689743dde6a09770ac6b659d3799dcc92cc5', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Bank holidays', 'Bank or public holidays do not have to be given as paid leave. An employer can choose to include bank holidays as part of a worker’s statutory annual leave.', 5, 'a7e46c34459428f6877263a2717bcf25ba033b8ac008598bab9969df87e9bc01', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Extra leave', 'An employer can choose to offer more leave than the legal minimum. They do not have to apply all the rules that apply to statutory leave to the extra leave. For example, a worker might need to be employed for a certain amount of time before they become entitled to it.', 6, '68ec21cec52c89ec6fb9148b24b53687483981de28ea852ec8fec71142994344', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Other aspects of holiday entitlement', 'Workers have the right to: build up holiday entitlement during certain types of leave, such as maternity, paternity, or adoption leave build up holiday entitlement while off work sick request holiday at the same time as sick leave', 7, 'a67d0de14684503b9cc72a19fae79ba3cd74225fa3cadd627c4ae65619c03da6', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
INSERT INTO corpus_chunks (source_table, source_id, domain, jurisdiction_code, authority_ref, source_url, title, heading, body_text, chunk_index, chunk_hash, source_type, effective_from, is_current, legal_topics) VALUES ('legal_sources', (SELECT id FROM legal_sources WHERE domain='employment_uk' AND source_id='govuk-holiday-entitlement'), 'employment_uk', 'EW', 'Holiday entitlement (https://www.gov.uk/holiday-entitlement-rights)', 'https://www.gov.uk/holiday-entitlement-rights', 'Holiday entitlement', 'Disputes', 'Paid annual leave is a legal right that an employer must provide. If a worker thinks their rights to leave and pay are not being met there are a number of ways to resolve the dispute.', 8, '010589c8452bce70521eb96495a3a82a76893bb513a47b75647c5fd6e2463ee0', 'govuk_guidance', NULL, true, ARRAY['employment']::text[]) ON CONFLICT (chunk_hash) DO NOTHING;
